//! Tauri titlebar Island and its daemon-backed session focus/search model.

use std::collections::HashSet;

use leptos::ev::KeyboardEvent;
use leptos::prelude::*;
use wasm_bindgen::JsCast;

use crate::daemon::{
    Daemon, PendingPermission, PermissionSnapshot, ProjectInfo, RequestSnapshot,
    RequestSnapshotState, SessionSummary,
};
use crate::search::fuzzy_score;
#[cfg(target_arch = "wasm32")]
use crate::sessions::is_recent;
use crate::sessions::{fmt_relative_time, project_for_root, session_root, split_origin};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IslandMode {
    Closed,
    Browse,
    Search,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum IslandPriority {
    Focused,
    Recent,
    Background,
}

#[derive(Clone, Debug, PartialEq)]
pub struct IslandSession {
    pub id: String,
    pub title: String,
    pub project: Option<String>,
    pub cwd: String,
    pub branch: Option<String>,
    pub origin: Option<String>,
    pub updated_at: String,
    pub turn_count: u32,
    pub is_focused: bool,
    pub priority: IslandPriority,
}

#[derive(Clone, Debug, PartialEq)]
pub enum IslandResult {
    Session(IslandSession),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum IslandAttentionState {
    NeedsHuman,
    Failed,
    Cancelling,
    Running,
}

impl IslandAttentionState {
    fn rank(self) -> u8 {
        match self {
            Self::NeedsHuman => 0,
            Self::Failed => 1,
            Self::Cancelling => 2,
            Self::Running => 3,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::NeedsHuman => "Needs attention",
            Self::Failed => "Failed",
            Self::Cancelling => "Stopping",
            Self::Running => "Running",
        }
    }

    fn class_name(self) -> &'static str {
        match self {
            Self::NeedsHuman => "is-needs-human",
            Self::Failed => "is-failed",
            Self::Cancelling => "is-cancelling",
            Self::Running => "is-running",
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct IslandAttentionItem {
    pub id: String,
    pub request_id: String,
    pub permission_id: Option<String>,
    pub session_id: Option<String>,
    pub session_title: String,
    pub project: Option<String>,
    pub tool: Option<String>,
    pub detail: String,
    pub updated_at: String,
    pub state: IslandAttentionState,
}

fn session_attention_metadata(
    sessions: &[IslandSession],
    session_id: Option<&str>,
) -> (String, Option<String>) {
    if let Some(session) =
        session_id.and_then(|id| sessions.iter().find(|session| session.id == id))
    {
        return (session.title.clone(), session.project.clone());
    }
    match session_id {
        Some(id) => (
            format!("Session {}", id.chars().take(8).collect::<String>()),
            None,
        ),
        None => ("Daemon request".to_string(), None),
    }
}

fn bounded_detail(value: &str) -> String {
    const LIMIT: usize = 240;
    let trimmed = value.trim();
    let mut chars = trimmed.chars();
    let prefix = chars.by_ref().take(LIMIT).collect::<String>();
    if chars.next().is_some() {
        format!("{prefix}…")
    } else {
        prefix
    }
}

fn request_updated_at(request: &RequestSnapshot) -> String {
    request
        .updated_at
        .as_deref()
        .or(request.finished_at.as_deref())
        .or(request.started_at.as_deref())
        .unwrap_or_default()
        .to_string()
}

/// Fold the daemon's global request/permission snapshots into a compact,
/// truthful activity projection. Permissions replace their matching waiting
/// request, terminal success/cancellation is omitted, and stale failure noise is
/// bounded to the newest three authoritative errored requests.
pub(crate) fn derive_attention_items(
    requests: &[RequestSnapshot],
    permissions: &[PermissionSnapshot],
    sessions: &[IslandSession],
) -> Vec<IslandAttentionItem> {
    let permission_requests: HashSet<&str> = permissions
        .iter()
        .map(|permission| permission.request_id.as_str())
        .collect();
    let mut items = Vec::new();

    for permission in permissions {
        let (session_title, project) =
            session_attention_metadata(sessions, permission.session_id.as_deref());
        let tool = (!permission.tool.trim().is_empty()).then(|| permission.tool.trim().to_string());
        let detail = if !permission.reason.trim().is_empty() {
            bounded_detail(&permission.reason)
        } else if let Some(tool) = tool.as_deref() {
            format!("Review requested access for {tool}")
        } else {
            "Review requested access".to_string()
        };
        items.push(IslandAttentionItem {
            id: format!("permission:{}", permission.permission_id),
            request_id: permission.request_id.clone(),
            permission_id: Some(permission.permission_id.clone()),
            session_id: permission.session_id.clone(),
            session_title,
            project,
            tool,
            detail,
            updated_at: permission.created_at.clone(),
            state: IslandAttentionState::NeedsHuman,
        });
    }

    let mut ordered_requests = requests.iter().collect::<Vec<_>>();
    ordered_requests.sort_by(|a, b| {
        request_updated_at(b)
            .cmp(&request_updated_at(a))
            .then_with(|| a.request_id.cmp(&b.request_id))
    });
    let mut failed_count = 0usize;
    for request in ordered_requests {
        if permission_requests.contains(request.request_id.as_str()) {
            continue;
        }
        let state = match request.state {
            RequestSnapshotState::Queued | RequestSnapshotState::Running => {
                IslandAttentionState::Running
            }
            RequestSnapshotState::WaitingForPermission => IslandAttentionState::NeedsHuman,
            RequestSnapshotState::Cancelling => IslandAttentionState::Cancelling,
            RequestSnapshotState::Errored if failed_count < 3 => {
                failed_count += 1;
                IslandAttentionState::Failed
            }
            RequestSnapshotState::Errored
            | RequestSnapshotState::Cancelled
            | RequestSnapshotState::Completed => continue,
        };
        let (session_title, project) =
            session_attention_metadata(sessions, request.session_id.as_deref());
        let detail = request
            .message
            .as_deref()
            .map(str::trim)
            .filter(|message| !message.is_empty())
            .map(bounded_detail)
            .unwrap_or_else(|| state.label().to_string());
        items.push(IslandAttentionItem {
            id: format!("request:{}", request.request_id),
            request_id: request.request_id.clone(),
            permission_id: request.permission_id.clone(),
            session_id: request.session_id.clone(),
            session_title,
            project,
            tool: None,
            detail,
            updated_at: request_updated_at(request),
            state,
        });
    }

    items.sort_by(|a, b| {
        a.state
            .rank()
            .cmp(&b.state.rank())
            .then_with(|| b.updated_at.cmp(&a.updated_at))
            .then_with(|| a.id.cmp(&b.id))
    });
    items
}

type IslandAttentionKey = (
    String,
    IslandAttentionState,
    Option<String>,
    String,
    Option<String>,
    Option<String>,
    String,
    String,
);

fn attention_render_key(item: &IslandAttentionItem) -> IslandAttentionKey {
    (
        item.id.clone(),
        item.state,
        item.permission_id.clone(),
        item.session_title.clone(),
        item.project.clone(),
        item.tool.clone(),
        item.detail.clone(),
        item.updated_at.clone(),
    )
}

fn permission_action_state(
    permission_id: Option<&str>,
    session_id: Option<&str>,
    focused_id: Option<&str>,
    has_decision_token: bool,
    pending: &[PendingPermission],
) -> Option<bool> {
    let permission_id = permission_id?;
    let session_id = session_id?;
    if !has_decision_token || focused_id != Some(session_id) {
        return None;
    }
    pending
        .iter()
        .find(|item| item.permission_id == permission_id && item.session_id == session_id)
        .map(|item| item.deciding)
}

fn compact_attention_counts(items: &[IslandAttentionItem]) -> (usize, usize) {
    let needs_human = items
        .iter()
        .filter(|item| item.state == IslandAttentionState::NeedsHuman)
        .count();
    let running = items
        .iter()
        .filter(|item| item.state == IslandAttentionState::Running)
        .count();
    (needs_human, running)
}

fn recently_updated(updated_at: &str) -> bool {
    #[cfg(target_arch = "wasm32")]
    {
        is_recent(updated_at)
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        // Browser time is intentionally unavailable in native unit tests.
        // Sorting remains fully deterministic there; production uses the
        // shared sessions-panel recency window above.
        let _ = updated_at;
        false
    }
}

/// Project daemon sessions into the compact metadata used by the Island.
pub(crate) fn derive_island_sessions(
    sessions: &[SessionSummary],
    projects: &[ProjectInfo],
    focused_id: Option<&str>,
) -> Vec<IslandSession> {
    let mut items: Vec<_> = sessions
        .iter()
        .map(|session| {
            let root = session_root(session).to_string();
            let project = session
                .owning_project
                .as_ref()
                .map(|owner| {
                    if owner.name.trim().is_empty() {
                        owner.id.clone()
                    } else {
                        owner.name.trim().to_string()
                    }
                })
                .or_else(|| {
                    project_for_root(projects, &root).map(|project| {
                        if project.name.trim().is_empty() {
                            project.id.clone()
                        } else {
                            project.name.trim().to_string()
                        }
                    })
                });
            let (origin, clean_title) = split_origin(&session.title);
            let title = if clean_title.trim().is_empty() {
                "(untitled)".to_string()
            } else {
                clean_title
            };
            let is_focused = focused_id == Some(session.id.as_str());
            let priority = if is_focused {
                IslandPriority::Focused
            } else if recently_updated(&session.updated_at) {
                IslandPriority::Recent
            } else {
                IslandPriority::Background
            };

            IslandSession {
                id: session.id.clone(),
                title,
                project,
                cwd: root,
                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
                origin,
                updated_at: session.updated_at.clone(),
                turn_count: session.turn_count,
                is_focused,
                priority,
            }
        })
        .collect();

    items.sort_by(|a, b| {
        b.is_focused
            .cmp(&a.is_focused)
            .then_with(|| b.updated_at.cmp(&a.updated_at))
            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
            .then_with(|| a.id.cmp(&b.id))
    });
    items
}

/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
pub(crate) fn island_search_text(item: &IslandSession) -> String {
    let state = match item.priority {
        IslandPriority::Focused => "focused",
        IslandPriority::Recent => "recent",
        IslandPriority::Background => "background",
    };
    let project = item.project.as_deref().unwrap_or_default();
    let branch = item.branch.as_deref().unwrap_or_default();
    let origin = item.origin.as_deref().unwrap_or_default();
    format!(
        "{} {} project:{} {} {} {} {} {} turns",
        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
    )
    .to_lowercase()
}

/// Search the Island corpus while preserving derivation order for an empty
/// query and using focus/recency only as small tie-breaks for real queries.
pub(crate) fn search_island(query: &str, items: &[IslandSession]) -> Vec<IslandResult> {
    let query = query.trim();
    if query.is_empty() {
        return items.iter().cloned().map(IslandResult::Session).collect();
    }

    let query_lower = query.to_lowercase();
    let mut scored: Vec<(u8, f64, usize, IslandSession)> = items
        .iter()
        .enumerate()
        .filter_map(|(index, item)| {
            let document_score = fuzzy_score(query, &island_search_text(item))?;
            let title = item.title.to_lowercase();
            let title_score = fuzzy_score(query, &item.title);
            let project = item.project.as_deref().map(str::to_lowercase);
            let project_score = project
                .as_deref()
                .and_then(|project| fuzzy_score(query, project));

            // Match category is a strict tier; fuzzy score only orders items
            // inside a tier, so a long fuzzy title can never outrank an exact
            // project (and metadata can never outrank a title/project match).
            let (tier, mut score) = if title == query_lower {
                (6, title_score.unwrap_or(document_score))
            } else if title.starts_with(&query_lower) {
                (5, title_score.unwrap_or(document_score))
            } else if project.as_deref() == Some(query_lower.as_str()) {
                (4, project_score.unwrap_or(document_score))
            } else if project
                .as_deref()
                .is_some_and(|project| project.starts_with(&query_lower))
            {
                (3, project_score.unwrap_or(document_score))
            } else if let Some(title_score) = title_score {
                (2, title_score)
            } else if let Some(project_score) = project_score {
                (1, project_score)
            } else {
                (0, document_score)
            };
            score += match item.priority {
                IslandPriority::Focused => 2.0,
                IslandPriority::Recent => 1.0,
                IslandPriority::Background => 0.0,
            };
            Some((tier, score, index, item.clone()))
        })
        .collect();

    scored.sort_by(|a, b| {
        b.0.cmp(&a.0)
            .then_with(|| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal))
            .then_with(|| a.2.cmp(&b.2))
            .then_with(|| a.3.id.cmp(&b.3.id))
    });
    scored
        .into_iter()
        .map(|(_, _, _, item)| IslandResult::Session(item))
        .collect()
}

fn option_id(session_id: &str) -> String {
    let encoded = session_id
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("island-option-{encoded}")
}

fn attention_panel_id(item_id: &str) -> String {
    let encoded = item_id
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("island-attention-{encoded}")
}

fn next_index(index: usize, len: usize) -> usize {
    if len == 0 {
        0
    } else {
        (index + 1) % len
    }
}

fn previous_index(index: usize, len: usize) -> usize {
    if len == 0 {
        0
    } else {
        (index + len - 1) % len
    }
}

#[component]
pub fn Island(
    daemon: Daemon,
    mode: RwSignal<IslandMode>,
    focus_request: RwSignal<u64>,
    on_open: Callback<IslandMode>,
) -> impl IntoView {
    let query = RwSignal::new(String::new());
    let selected_index = RwSignal::new(0usize);
    let previous_mode = RwSignal::new(IslandMode::Closed);
    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
    let last_focus_request = RwSignal::new(0u64);
    let recency_tick = RwSignal::new(0u64);
    let expanded_attention = RwSignal::new(None::<String>);
    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
    let popover_ref: NodeRef<leptos::html::Section> = NodeRef::new();

    #[cfg(target_arch = "wasm32")]
    let recency_interval =
        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(60_000, move || {
            recency_tick.update(|tick| *tick = tick.wrapping_add(1))
        }));
    #[cfg(target_arch = "wasm32")]
    on_cleanup(move || drop(recency_interval));

    #[cfg(target_arch = "wasm32")]
    let attention_interval = {
        let daemon = daemon.clone();
        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(3_000, move || {
            daemon.fetch_attention();
        }))
    };
    #[cfg(target_arch = "wasm32")]
    on_cleanup(move || drop(attention_interval));

    let session_list = daemon.session_list;
    let request_list = daemon.request_list;
    let permission_list = daemon.permission_list;
    let pending_permissions = daemon.pending_permissions;
    let active_decision_token = daemon.active_decision_token;
    let projects = daemon.projects;
    let focused_id = daemon.session_id;
    let daemon = StoredValue::new(daemon);

    // The closed chip is an ambient session surface, not merely an overlay
    // trigger. Prime its catalogue on mount so a restored focused session and
    // recent count render without requiring the operator to open Search first.
    // Opening still refreshes both sources below to avoid stale browse results.
    {
        let daemon = daemon.get_value();
        daemon.fetch_sessions();
        daemon.fetch_projects();
        daemon.fetch_attention();
    }

    let sessions = Memo::new(move |_| {
        let _ = recency_tick.get();
        derive_island_sessions(
            &session_list.get(),
            &projects.get(),
            focused_id.get().as_deref(),
        )
    });
    let attention_items = Memo::new(move |_| {
        derive_attention_items(&request_list.get(), &permission_list.get(), &sessions.get())
    });
    let needs_human_count = Memo::new(move |_| compact_attention_counts(&attention_items.get()).0);
    let running_count = Memo::new(move |_| compact_attention_counts(&attention_items.get()).1);
    let results = Memo::new(move |_| {
        let mut matches = search_island(&query.get(), &sessions.get());
        if mode.get() == IslandMode::Search {
            matches.truncate(20);
        }
        matches
    });

    Effect::new(move |_| {
        let next = mode.get();
        let request = focus_request.get();
        let previous = previous_mode.get_untracked();
        let previous_request = last_focus_request.get_untracked();
        if next != IslandMode::Closed && previous == IslandMode::Closed {
            let active = web_sys::window()
                .and_then(|window| window.document())
                .and_then(|document| document.active_element())
                .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok());
            previous_focus.set_value(active);
            query.set(String::new());
            selected_index.set(0);
            expanded_attention.set(None);
            let daemon = daemon.get_value();
            daemon.fetch_sessions();
            daemon.fetch_projects();
            daemon.fetch_attention();
        }
        let should_focus = next != IslandMode::Closed
            && (previous == IslandMode::Closed || next != previous || request != previous_request);
        if should_focus {
            request_animation_frame(move || {
                if let Some(input) = input_ref.get() {
                    let _ = input.focus();
                    if next == IslandMode::Search {
                        input.select();
                    }
                }
            });
        } else if next == IslandMode::Closed && previous != IslandMode::Closed {
            request_animation_frame(move || {
                if let Some(element) = previous_focus.get_value().filter(|el| el.is_connected()) {
                    let _ = element.focus();
                } else if let Some(chip) = chip_ref.get() {
                    let _ = chip.focus();
                }
            });
        }
        previous_mode.set(next);
        last_focus_request.set(request);
    });

    Effect::new(move |_| {
        let len = results.get().len();
        if len == 0 || selected_index.get() >= len {
            selected_index.set(0);
        }
    });

    // A polling update can remove or replace the disclosure that currently
    // owns focus. Restore the combobox on the next frame instead of leaving an
    // aria-modal dialog whose next Tab escapes from a detached element.
    Effect::new(move |_| {
        let _ = attention_items.get();
        let _ = pending_permissions.get();
        let _ = active_decision_token.get();
        if mode.get() == IslandMode::Closed {
            return;
        }
        request_animation_frame(move || {
            let Some(popover) = popover_ref.get() else {
                return;
            };
            let active = web_sys::window()
                .and_then(|window| window.document())
                .and_then(|document| document.active_element());
            let contains_active = active.is_some_and(|active| {
                popover
                    .clone()
                    .unchecked_into::<web_sys::Node>()
                    .contains(Some(&active.unchecked_into::<web_sys::Node>()))
            });
            if !contains_active {
                if let Some(input) = input_ref.get() {
                    let _ = input.focus();
                }
            }
        });
    });

    let selected_option_id = move || {
        results
            .get()
            .get(selected_index.get())
            .map(|result| match result {
                IslandResult::Session(item) => option_id(&item.id),
            })
            .unwrap_or_default()
    };
    let close = move || mode.set(IslandMode::Closed);
    let on_keydown = move |event: KeyboardEvent| {
        if mode.get_untracked() == IslandMode::Closed || event.is_composing() {
            return;
        }
        let key = event.key();
        if key == "Escape" {
            event.prevent_default();
            event.stop_propagation();
            close();
            return;
        }
        if key == "Tab" {
            // Phase 2 adds real disclosure/action controls. Keep them inside the
            // modal focus loop while leaving session rows on the combobox's
            // active-descendant path.
            event.prevent_default();
            let mut focusable = Vec::<web_sys::HtmlElement>::new();
            if let Some(popover) = popover_ref.get() {
                if let Ok(nodes) = popover.query_selector_all(
                    ".island-search__input, .island-attention__summary, .island-attention__deny:not([disabled]), .island-attention__approve:not([disabled]), .island-attention__open:not([disabled])",
                ) {
                    for index in 0..nodes.length() {
                        if let Some(element) = nodes
                            .item(index)
                            .and_then(|node| node.dyn_into::<web_sys::HtmlElement>().ok())
                        {
                            focusable.push(element);
                        }
                    }
                }
            }
            if focusable.is_empty() {
                if let Some(input) = input_ref.get() {
                    let _ = input.focus();
                }
                return;
            }
            let current = event
                .target()
                .and_then(|target| target.dyn_into::<web_sys::Node>().ok());
            let current_index = focusable
                .iter()
                .position(|element| {
                    element
                        .clone()
                        .unchecked_into::<web_sys::Node>()
                        .is_same_node(current.as_ref())
                })
                .unwrap_or(0);
            let next = if event.shift_key() {
                (current_index + focusable.len() - 1) % focusable.len()
            } else {
                (current_index + 1) % focusable.len()
            };
            let _ = focusable[next].focus();
            return;
        }

        // Disclosure buttons use native Enter/Space activation. Session arrow
        // navigation and Enter-to-focus apply only while the combobox owns DOM
        // focus, preventing a disclosure keypress from switching another row.
        let from_search = event
            .target()
            .and_then(|target| target.dyn_into::<web_sys::HtmlElement>().ok())
            .is_some_and(|element| element.class_list().contains("island-search__input"));
        if !from_search {
            return;
        }

        let len = results.get_untracked().len();
        match key.as_str() {
            "ArrowDown" => {
                event.prevent_default();
                selected_index.update(|index| *index = next_index(*index, len));
                request_animation_frame(move || {
                    let id = selected_option_id();
                    if let Some(option) = web_sys::window()
                        .and_then(|window| window.document())
                        .and_then(|document| document.get_element_by_id(&id))
                    {
                        option.scroll_into_view();
                    }
                });
            }
            "ArrowUp" => {
                event.prevent_default();
                selected_index.update(|index| *index = previous_index(*index, len));
                request_animation_frame(move || {
                    let id = selected_option_id();
                    if let Some(option) = web_sys::window()
                        .and_then(|window| window.document())
                        .and_then(|document| document.get_element_by_id(&id))
                    {
                        option.scroll_into_view();
                    }
                });
            }
            "Enter" => {
                event.prevent_default();
                if let Some(IslandResult::Session(item)) =
                    results.get_untracked().get(selected_index.get_untracked())
                {
                    daemon
                        .get_value()
                        .switch_session(item.id.clone(), item.title.clone());
                    close();
                }
            }
            _ => {}
        }
    };

    let focused_session = Memo::new(move |_| {
        sessions
            .get()
            .into_iter()
            .find(|session| session.is_focused)
    });
    let recent_count = Memo::new(move |_| {
        sessions
            .get()
            .iter()
            .filter(|session| !session.is_focused && session.priority == IslandPriority::Recent)
            .count()
    });
    let chip_status = move || {
        let needs_human = needs_human_count.get();
        let running = running_count.get();
        if needs_human == 1 {
            "1 needs attention".to_string()
        } else if needs_human > 1 {
            format!("{needs_human} need attention")
        } else if running > 0 {
            format!("{running} running")
        } else {
            format!("{} recent", recent_count.get())
        }
    };
    let attention_announcement = move || chip_status();
    let chip_label = move || {
        let state = chip_status();
        focused_session.get().map_or_else(
            || format!("Ocean, no focused session. {state}. Open session browser"),
            |session| {
                let project = session
                    .project
                    .as_deref()
                    .map(|value| format!(", {value}"))
                    .unwrap_or_default();
                format!(
                    "Focused session: {}{}. {}. Open session browser",
                    session.title, project, state
                )
            },
        )
    };

    view! {
        <section class="island-host" on:keydown=on_keydown>
            <button
                class=move || {
                    if needs_human_count.get() > 0 {
                        "island-chip is-attention"
                    } else if running_count.get() > 0 {
                        "island-chip is-running"
                    } else {
                        "island-chip"
                    }
                }
                type="button"
                node_ref=chip_ref
                aria-label=chip_label
                aria-haspopup="dialog"
                aria-expanded=move || (mode.get() != IslandMode::Closed).to_string()
                aria-controls="island-popover"
                on:click=move |_| {
                    if mode.get_untracked() == IslandMode::Closed {
                        on_open.run(IslandMode::Browse);
                    } else {
                        close();
                    }
                }
            >
                <span
                    class=move || {
                        if needs_human_count.get() > 0 {
                            "island-chip__dot is-attention"
                        } else if running_count.get() > 0 {
                            "island-chip__dot is-running"
                        } else if focused_session.get().is_none() {
                            "island-chip__dot is-empty"
                        } else {
                            "island-chip__dot"
                        }
                    }
                    aria-hidden="true"
                ></span>
                <span class="island-chip__title">
                    {move || focused_session.get().map(|item| item.title).unwrap_or_else(|| "Ocean · no session".into())}
                </span>
                <Show when=move || focused_session.get().and_then(|item| item.project).is_some()>
                    <span class="island-chip__separator" aria-hidden="true">"·"</span>
                    <span class="island-chip__project">
                        {move || focused_session.get().and_then(|item| item.project).unwrap_or_default()}
                    </span>
                </Show>
                <span class="island-chip__separator" aria-hidden="true">"·"</span>
                <span class="island-chip__count">{move || chip_status()}</span>
            </button>
            <span class="island-live" aria-live="polite" aria-atomic="true">
                {move || attention_announcement()}
            </span>

            <Show when=move || mode.get() != IslandMode::Closed>
                <div class="island-scrim" aria-hidden="true" on:click=move |_| close()></div>
                <section
                    id="island-popover"
                    class="island-popover"
                    node_ref=popover_ref
                    role="dialog"
                    aria-modal="true"
                    aria-label="Focus a session"
                >
                    <div class="island-search">
                        <input
                            class="island-search__input"
                            type="search"
                            role="combobox"
                            aria-label="Search sessions"
                            aria-autocomplete="list"
                            aria-expanded="true"
                            aria-controls="island-results"
                            aria-activedescendant=move || {
                                let id = selected_option_id();
                                (!id.is_empty()).then_some(id)
                            }
                            placeholder="Search sessions, projects, paths, branches…"
                            autocomplete="off"
                            node_ref=input_ref
                            prop:value=move || query.get()
                            on:input=move |event| {
                                query.set(event_target_value(&event));
                                selected_index.set(0);
                            }
                        />
                    </div>
                    <Show when=move || !attention_items.get().is_empty()>
                        <section class="island-attention" aria-labelledby="island-attention-title">
                            <header class="island-attention__header">
                                <span id="island-attention-title">"Activity"</span>
                                <span>{move || {
                                    let count = attention_items.get().len();
                                    if count == 1 {
                                        "1 item".to_string()
                                    } else {
                                        format!("{count} items")
                                    }
                                }}</span>
                            </header>
                            <div class="island-attention__list">
                                <For
                                    each=move || attention_items.get()
                                    key=attention_render_key
                                    children=move |item| {
                                        let item_class = format!(
                                            "island-attention__item {}",
                                            item.state.class_name(),
                                        );
                                        let item_id_for_aria = item.id.clone();
                                        let item_id_for_show = item.id.clone();
                                        let item_id_for_toggle = item.id.clone();
                                        let panel_id = attention_panel_id(&item.id);
                                        let panel_id_for_control = panel_id.clone();
                                        let panel_id_value = StoredValue::new_local(panel_id);
                                        let state_label = item.state.label();
                                        let session_title = item.session_title.clone();
                                        let summary_detail = item.detail.clone();
                                        let detail_text = StoredValue::new_local(item.detail.clone());
                                        let detail_project = StoredValue::new_local(
                                            item.project.clone().unwrap_or_default(),
                                        );
                                        let detail_tool = StoredValue::new_local(
                                            item.tool.clone().unwrap_or_default(),
                                        );
                                        let detail_time = StoredValue::new_local(
                                            if item.updated_at.is_empty() {
                                                String::new()
                                            } else {
                                                fmt_relative_time(&item.updated_at)
                                            },
                                        );
                                        let open_unavailable = item.session_id.is_none();
                                        let open_target = StoredValue::new_local((
                                            item.session_id.clone(),
                                            item.session_title.clone(),
                                        ));
                                        let permission_id =
                                            StoredValue::new_local(item.permission_id.clone());
                                        let permission_session =
                                            StoredValue::new_local(item.session_id.clone());
                                        // Some(deciding) means this Surface owns the
                                        // matching live permission and its decision
                                        // token. None is deliberately read-only.
                                        let permission_action = Memo::new(move |_| {
                                            let permission_id_value = permission_id.get_value();
                                            let permission_session_value =
                                                permission_session.get_value();
                                            permission_action_state(
                                                permission_id_value.as_deref(),
                                                permission_session_value.as_deref(),
                                                focused_id.get().as_deref(),
                                                active_decision_token.get().is_some(),
                                                &pending_permissions.get(),
                                            )
                                        });
                                        view! {
                                            <article class=item_class>
                                                <button
                                                    class="island-attention__summary"
                                                    type="button"
                                                    aria-expanded=move || {
                                                        (expanded_attention.get().as_deref()
                                                            == Some(item_id_for_aria.as_str()))
                                                            .to_string()
                                                    }
                                                    aria-controls=panel_id_for_control
                                                    on:click=move |_| {
                                                        expanded_attention.update(|expanded| {
                                                            if expanded.as_deref()
                                                                == Some(item_id_for_toggle.as_str())
                                                            {
                                                                *expanded = None;
                                                            } else {
                                                                *expanded = Some(item_id_for_toggle.clone());
                                                            }
                                                        });
                                                    }
                                                >
                                                    <span class="island-attention__state">
                                                        <span aria-hidden="true"></span>
                                                        {state_label}
                                                    </span>
                                                    <span class="island-attention__session">{session_title}</span>
                                                    <span class="island-attention__summary-detail">{summary_detail}</span>
                                                    <span class="island-attention__disclosure" aria-hidden="true">
                                                        <crate::icons::ChevronDown />
                                                    </span>
                                                </button>
                                                <Show when=move || {
                                                    expanded_attention.get().as_deref()
                                                        == Some(item_id_for_show.as_str())
                                                }>
                                                    <div
                                                        id=move || panel_id_value.get_value()
                                                        class="island-attention__details"
                                                    >
                                                        <div class="island-attention__meta">
                                                            <span>{move || detail_project.get_value()}</span>
                                                            <span>{move || detail_tool.get_value()}</span>
                                                            <span>{move || detail_time.get_value()}</span>
                                                        </div>
                                                        <p>{move || detail_text.get_value()}</p>
                                                        <Show when=move || permission_action.get().is_some()>
                                                            <div class="island-attention__actions">
                                                                <button
                                                                    class="island-attention__deny"
                                                                    type="button"
                                                                    disabled=move || {
                                                                        permission_action.get().unwrap_or(true)
                                                                    }
                                                                    on:click=move |_| {
                                                                        if let Some(permission_id) =
                                                                            permission_id.get_value()
                                                                        {
                                                                            daemon.get_value().decide_permission(
                                                                                permission_id,
                                                                                false,
                                                                            );
                                                                        }
                                                                    }
                                                                >
                                                                    "Deny"
                                                                </button>
                                                                <button
                                                                    class="island-attention__approve"
                                                                    type="button"
                                                                    disabled=move || {
                                                                        permission_action.get().unwrap_or(true)
                                                                    }
                                                                    on:click=move |_| {
                                                                        if let Some(permission_id) =
                                                                            permission_id.get_value()
                                                                        {
                                                                            daemon.get_value().decide_permission(
                                                                                permission_id,
                                                                                true,
                                                                            );
                                                                        }
                                                                    }
                                                                >
                                                                    {move || if permission_action.get() == Some(true) {
                                                                        "Working…"
                                                                    } else {
                                                                        "Approve"
                                                                    }}
                                                                </button>
                                                            </div>
