    width: min(210px, 36%);
  }

  .has-workspace-open .ocean-brand {
    display: none;
  }

}

@media (prefers-reduced-motion: reduce) {
  .island-chip,
  .island-result,
  .island-attention__summary,
  .island-attention__disclosure {
    transition: none;
  }
}

