2015	    fn connect_permission_stream(&self, active_session_id: String, generation: u64) {
2016	        let url = self.url.get_untracked();
2017	        let sse_generation = self.sse_generation;
2018	        let pending = self.pending_permissions;
2019	        #[cfg(target_arch = "wasm32")]
2020	        let permission_event_source = Arc::clone(&self.permission_event_source);
2021	
2022	        spawn_local(async move {
2023	            loop {
2024	                if sse_generation.get_untracked() != generation {
2025	                    break;
2026	                }
2027	                let events_url = format!("{}/v1/events", url.trim_end_matches('/'));
2028	                let mut es = match EventSource::new(&events_url) {
2029	                    Ok(es) => es,
2030	                    Err(_) => {
2031	                        gloo_timers::future::TimeoutFuture::new(2_000).await;
2032	                        continue;
2033	                    }
