const { chromium } = require('playwright');
(async()=>{const browser=await chromium.launch({headless:true});const page=await browser.newPage();await page.setContent('<section id=p><input id=i><button id=o>Open session</button><button id=a style="display:none">Approve</button></section>');
const out=await page.evaluate(async()=>{o.focus();const before=document.activeElement.id;o.disabled=true;o.style.display='none';a.style.display='inline-block';await new Promise(requestAnimationFrame);return {before,after:document.activeElement.id,tag:document.activeElement.tagName,contains:p.contains(document.activeElement)};});console.log(JSON.stringify(out));await browser.close();})();
NODE

