const out=await page.evaluate(async()=>{a.focus();const before=document.activeElement.id;actions.remove();await new Promise(requestAnimationFrame);return {before,after:document.activeElement.id,tag:document.activeElement.tagName,contains:p.contains(document.activeElement)};});console.log(JSON.stringify(out));await browser.close();})();
